export function getPlanetText(planet: string, sign: string, house: number, childName: string, adjSuffix: string): string {
  const fn = PLANET_INTERPRETATIONS[planet]?.[sign];
  if (fn) return fn(childName, house, adjSuffix);
  return `Con ${planet} en ${sign} en la casa ${house}, ${childName} tiene una energía única que combina la esencia de ${planet} con las cualidades de ${sign} en el área de vida señalada por la casa ${house}.`;
}

