type CompatFn = (childName: string, adjSuffix: string) => string;

export const COMPATIBILITY_TEXTS: Record<string, CompatFn> = {
  Aries: (n) => `Como niño con Sol en Aries, ${n} necesita padres que sean activos, directos y que no tengan miedo de su energía. El mayor regalo que pueden darle es libertad para actuar, espacio para liderar y la seguridad de que sus impulsos serán canalizados, no reprimidos.\n\n✦ Lo que más necesita de sus padres: Validación de su liderazgo. Cuando ${n} toma la iniciativa, aunque no salga perfecto, necesita escuchar "lo intentaste y eso vale". Límites con explicación: decirle "no" sin razón genera rebelión en Aries.\n\n✦ Cómo comunicarse mejor: Directo, breve y sin rodeos. Los Aries se desconectan de los sermones largos. Una frase contundente tiene más impacto que diez minutos de explicaciones.\n\n✦ Lo que le estresa: La pasividad, la lentitud excesiva, sentir que no puede avanzar. La sensación de estar atrapado puede generar explosiones emocionales en ${n}.\n\n✦ Lo que le sana: El movimiento físico, las aventuras, los nuevos comienzos. Después de un momento difícil, proponer una actividad nueva y activa restablece el equilibrio de ${n} más rápido que cualquier conversación.`,
  Tauro: (n) => `Como niño con Sol en Tauro, ${n} necesita padres que sean constantes, pacientes y que construyan confianza a través de la consistencia en el tiempo. La seguridad no se gana con palabras para Tauro: se gana con actos repetidos a lo largo de los años.\n\n✦ Lo que más necesita de sus padres: Rutinas estables y promesas cumplidas. Cada vez que se cumple lo prometido, el mundo de ${n} se hace un poco más seguro. Contacto físico: abrazos, caricias, presencia corporal que diga "estoy aquí".\n\n✦ Cómo comunicarse mejor: Con calma, sin prisas y dando tiempo para que procese. ${n} necesita tiempo entre la pregunta y la respuesta. Presionar genera el efecto contrario: terquedad y cierre.\n\n✦ Lo que le estresa: Los cambios repentinos, la inestabilidad, las promesas rotas. Para ${n}, que le digan que van a hacer algo y luego no suceda genera una herida profunda en la confianza.\n\n✦ Lo que le sana: El contacto con la naturaleza, la comida rica, la música, los rituales familiares que se repiten. La sensorialidad es su idioma de sanación.`,
  Géminis: (n) => `Como niño con Sol en Géminis, ${n} necesita padres que sean curiosos, comunicativos y que disfruten genuinamente de explorar el mundo junto a él. El aburrimiento es el peor escenario para un niño Géminis.\n\n✦ Lo que más necesita de sus padres: Conversaciones reales y tiempo de calidad intelectual. Leer juntos, hacer preguntas, ver documentales, debatir ideas. ${n} necesita un compañero de exploración más que un maestro con respuestas.\n\n✦ Cómo comunicarse mejor: Con variedad y creatividad. La misma conversación de siempre no funciona. Cambiar el formato mantiene abierta la comunicación con ${n}.\n\n✦ Lo que le estresa: La monotonía, las reglas sin explicación lógica, sentir que no puede preguntar lo que genuinamente le interesa.\n\n✦ Lo que le sana: El movimiento, las palabras, la estimulación mental. Cuando ${n} está inquieto emocionalmente, leer juntos o simplemente hablar mientras camina puede restablecer su equilibrio interno.`,
  Cáncer: (n) => `Como niño con Sol en Cáncer, ${n} necesita padres que sean emocionalmente presentes, que hagan del hogar un lugar verdaderamente seguro y que entiendan que su mundo interior es tan real e importante como el externo.\n\n✦ Lo que más necesita de sus padres: Presencia emocional auténtica. No basta con estar en el mismo cuarto: ${n} necesita sentir que sus emociones son recibidas y comprendidas. Los rituales de conexión son su ancla emocional.\n\n✦ Cómo comunicarse mejor: Desde la emoción, no desde la lógica. "Entiendo que estás triste" abre más puertas que "no tienes razón para estar triste". Validar primero, resolver después.\n\n✦ Lo que le estresa: Las discusiones familiares, los ambientes fríos o distantes. ${n} absorbe el clima emocional familiar como una esponja y lo lleva en el cuerpo.\n\n✦ Lo que le sana: El calor del hogar, la comida preparada con amor, el contacto físico y saber con certeza que es amado incondicionalmente.`,
  Leo: (n) => `Como niño con Sol en Leo, ${n} necesita padres que celebren su singularidad con genuino entusiasmo, que le den escenarios donde brillar y que entiendan que su necesidad de reconocimiento no es vanidad: es una necesidad del alma.\n\n✦ Lo que más necesita de sus padres: Reconocimiento auténtico y frecuente. No exagerado ni vacío, sino genuino: "vi lo que hiciste y es notable". Tiempo de calidad como protagonista: que los padres le escuchen de verdad, sin distracciones.\n\n✦ Cómo comunicarse mejor: Con entusiasmo y expresividad. Los Leos responden al calor emocional. Una conversación cálida, con contacto visual y sin el celular de por medio, abre el corazón de ${n} completamente.\n\n✦ Lo que le estresa: Sentirse invisible, ser ignorado/a, recibir críticas públicas o comparaciones con otros.\n\n✦ Lo que le sana: El juego creativo, el baile, la actuación, ser el protagonista de algo. Después de un momento difícil, proponer una actividad donde pueda brillar restablece su energía y su confianza.`,
  Virgo: (n) => `Como niño con Sol en Virgo, ${n} necesita padres que valoren su dedicación y su precisión, que le ayuden a gestionar su perfeccionismo con compasión y que entiendan que su necesidad de hacer las cosas bien viene de un lugar de genuina integridad.\n\n✦ Lo que más necesita de sus padres: Reconocimiento del esfuerzo más que del resultado. "Trabajaste muy duro en esto y se nota" tiene más valor para ${n} que un simple "quedó perfecto". Ayuda para gestionar la autocrítica.\n\n✦ Cómo comunicarse mejor: Con claridad, precisión y pasos concretos. "Necesito que hagas X antes de Y" funciona mejor que instrucciones vagas. ${n} trabaja mejor cuando sabe exactamente qué se espera de él.\n\n✦ Lo que le estresa: El desorden, la improvisación excesiva, sentir que no puede hacer algo lo suficientemente bien.\n\n✦ Lo que le sana: Las rutinas, el orden, los proyectos con resultados medibles y el reconocimiento de sus contribuciones prácticas.`,
  Libra: (n) => `Como niño con Sol en Libra, ${n} necesita padres que modelen la resolución de conflictos de manera justa y respetuosa, que creen entornos armoniosos y que valoren tanto su sensibilidad estética como su sentido profundo de la justicia.\n\n✦ Lo que más necesita de sus padres: Equidad genuina. ${n} nota inmediatamente cuando algo no es justo. Apoyo para tomar decisiones: la indecisión de Libra necesita andamiaje, no presión.\n\n✦ Cómo comunicarse mejor: Ofreciendo opciones equilibradas y tiempo para decidir. "¿Qué te parece más justo?" es una pregunta que activa lo mejor de ${n}.\n\n✦ Lo que le estresa: Las discusiones sin resolución, las situaciones injustas, tener que elegir entre cosas que ama por igual.\n\n✦ Lo que le sana: La belleza, la música, los espacios ordenados y armoniosos, las conversaciones donde todos son escuchados con respeto.`,
  Escorpio: (n) => `Como niño con Sol en Escorpio, ${n} necesita padres que sean absolutamente honestos, que respeten su profundidad y que no se asusten de la intensidad de su mundo emocional e interior.\n\n✦ Lo que más necesita de sus padres: Honestidad radical. ${n} detecta la mentira con una precisión asombrosa. La confianza construida desde la verdad es irrompible. Respeto por su privacidad: no presionar para que comparta lo que no está listo para compartir.\n\n✦ Cómo comunicarse mejor: Profundo, directo y sin suavizar la realidad artificialmente. Escorpio prefiere una verdad difícil a una mentira piadosa.\n\n✦ Lo que le estresa: La deshonestidad, la superficialidad forzada, sentir que sus emociones profundas son ignoradas o minimizadas.\n\n✦ Lo que le sana: El tiempo en privado, las conversaciones profundas cuando él las inicia, el reconocimiento de su intensidad como fortaleza.`,
  Sagitario: (n) => `Como niño con Sol en Sagitario, ${n} necesita padres que sean abiertos de mente, que expandan activamente su mundo y que entiendan que su necesidad de libertad y exploración no es rebeldía: es su naturaleza más esencial.\n\n✦ Lo que más necesita de sus padres: Espacios de libertad real dentro de un marco lo suficientemente amplio para que pueda explorar y aprender. Aventuras compartidas: viajes, nuevas experiencias, conversaciones filosóficas.\n\n✦ Cómo comunicarse mejor: Con honestidad y entusiasmo. Los Sagitario no toleran la hipocresía. Las metáforas y las historias son su lenguaje preferido.\n\n✦ Lo que le estresa: Sentirse atrapado/a, las reglas rígidas sin sentido aparente, la monotonía.\n\n✦ Lo que le sana: La naturaleza, el movimiento, las nuevas experiencias y las conversaciones sobre el sentido de la vida.`,
  Capricornio: (n) => `Como niño con Sol en Capricornio, ${n} necesita padres que reconozcan su madurez sin exigirle que crezca más rápido de lo que debe, que valoren su esfuerzo con la misma intensidad que valoran sus logros y que le enseñen que el descanso es tan sagrado como la productividad.\n\n✦ Lo que más necesita de sus padres: Reconocimiento del esfuerzo antes que del resultado. "Trabajaste muy duro" importa más que el calificativo o el premio. Permiso para ser niño: ${n} a veces carga demasiada responsabilidad; necesita que le recuerden que puede jugar sin propósito.\n\n✦ Cómo comunicarse mejor: Con claridad, respeto y metas. Los acuerdos claros generan confianza y cooperación en ${n}.\n\n✦ Lo que le estresa: El caos sin estructura, sentir que sus esfuerzos no son reconocidos, las metas poco claras.\n\n✦ Lo que le sana: Los logros completados, el reconocimiento genuino, el descanso bien merecido.`,
  Acuario: (n) => `Como niño con Sol en Acuario, ${n} necesita padres que respeten su originalidad sin intentar normalizarla, que estimulen su pensamiento crítico y que entiendan que su necesidad de ser diferente no es un problema a resolver sino una misión a acompañar.\n\n✦ Lo que más necesita de sus padres: Respeto por su singularidad. Cada vez que sus padres dicen "me gusta cómo piensas" o "esa es una perspectiva interesante", el corazón de ${n} se abre completamente. Espacio para su independencia.\n\n✦ Cómo comunicarse mejor: Con lógica, respeto y apertura al debate. Los Acuario no aceptan "porque lo digo yo" como respuesta. Una explicación razonada genera más respeto que la autoridad sin fundamento.\n\n✦ Lo que le estresa: Que le fuercen a encajar en moldes que no son para él, la hipocresía, las reglas que parecen arbitrarias.\n\n✦ Lo que le sana: El tiempo con sus amigos que comparten sus valores, los proyectos innovadores y saber que sus padres lo ven como el ser singular y valioso que es.`,
  Piscis: (n) => `Como niño con Sol en Piscis, ${n} necesita padres que sean emocionalmente gentiles, que protejan su sensibilidad sin sobreprotegerle y que entiendan que su mundo interior es tan real e importante como el mundo exterior.\n\n✦ Lo que más necesita de sus padres: Gentileza radical en el trato. ${n} absorbe los tonos emocionales directamente en su sistema nervioso. Un tono de voz cálido tiene un efecto profundo en su bienestar. Protección emocional sin encierro: aprender a navegar el mundo desde la sensibilidad.\n\n✦ Cómo comunicarse mejor: Con suavidad, imágenes y metáforas. El arte y la música pueden ser vehículos de comunicación más poderosos que las palabras directas para ${n}.\n\n✦ Lo que le estresa: Los ambientes fríos, ruidosos o agresivos; las exigencias de dureza emocional. También le afecta absorber el estrés de sus cuidadores.\n\n✦ Lo que le sana: El agua, la música, el arte, la naturaleza tranquila y la sensación de estar completamente seguro y amado tal como es.`,
};
